{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.n24q02m/better-email-mcp",
  "description": "IMAP/SMTP MCP server for Email with composite tools. Multi-account, auto-discovery.",
  "repository": {
    "url": "https://github.com/n24q02m/better-email-mcp.git",
    "source": "github"
  },
  "version": "1.35.0-beta.2",
  "packages": [
    {
      "registryType": "npm",
      "identifier": "@n24q02m/better-email-mcp",
      "version": "1.35.0-beta.2",
      "runtimeHint": "npx",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "description": "Email credentials (format: user@gmail.com:app-password). Multiple accounts: comma-separated.",
          "isRequired": true,
          "isSecret": true,
          "name": "EMAIL_CREDENTIALS"
        }
      ]
    },
    {
      "registryType": "oci",
      "identifier": "docker.io/n24q02m/better-email-mcp:latest",
      "runtimeHint": "docker",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "description": "Email credentials (format: user@gmail.com:app-password). Multiple accounts: comma-separated.",
          "isRequired": true,
          "isSecret": true,
          "name": "EMAIL_CREDENTIALS"
        }
      ]
    }
  ]
}
